/bin/bash -lc "cat > openlibrary/coverstore/archive.py <<'EOF'
\"\"\"Stage covers in 10,000-image ZIPs and reconcile verified archive.org uploads.

A cover remains readable from localdisk until all four ZIPs for its batch have
been verified in their archive.org items.  "'``archived`` means staged in ZIPs;
``uploaded`` means its database filenames point to verified remote copies.
"""

from contextlib import contextmanager
import fcntl
import os
import re
from subprocess import run
import time
import zipfile

from openlibrary.coverstore import config, db


SIZES = ('"'', 's', 'm', 'l')
BATCH_SIZE = 10_000
IMAGE_NAME = re.compile(r'"'^(?P<id>'"\\d{10})(?:-(?P<size>[SML]))?\\.(?P<ext>[a-zA-Z0-9]+)"'$'"')


def _size(size):
    size = (size or '').lower()
    if size not in SIZES:
        raise ValueError(f'Invalid cover size: {size}')
    return size


class Cover:
    \"\"\"A cover record and its canonical archive.org naming convention.\"\"\"

    def __init__(self, attributes):
        self.attributes = attributes
        self.id = int(attributes['id'])

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        cover_id = int(cover_id)
        if not 0 <= cover_id < 10_000_000_000:
            raise ValueError('Cover ID must fit in ten digits')
        digits = f'{cover_id:010d}'
        return digits[:4], digits[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        size = _size(size)
        if protocol not in ('http', 'https'):
            raise ValueError('Protocol must be http or https')
        if not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('Invalid extension')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        archive_name = f'{item}_{batch_id}.zip'
        suffix = f'-{size.upper()}' if size else ''
        filename = f'{int(cover_id):010d}{suffix}.{ext}'
        return f'{protocol}://archive.org/download/{item}/{archive_name}/{filename}'

    def local_files(self):
        for size in SIZES:
            field = f'filename_{size}' if size else 'filename'
            filename = self.attributes.get(field)
            yield size, os.path.join(config.data_root, 'localdisk', filename) if filename else None

    def has_valid_files(self):
        return all(path and os.path.isfile(path) for _, path in self.local_files())

    def delete_files(self):
        for _, path in self.local_files():
            if path and os.path.isfile(path):
                os.remove(path)


class Batch:
    \"\"\"One 10,000-cover batch within a million-cover archive.org item.\"\"\"

    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = None if size is None else _size(size)

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item_id, batch_id = int(item_id), int(batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('Item or batch ID out of range')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls._norm_ids(item_id, batch_id)
        size = _size(size)
        if not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('Invalid extension')
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @property
    def start_id(self):
        return int(self.item_id) * 1_000_000 + int(self.batch_id) * BATCH_SIZE

    def _sizes(self):
        return SIZES if self.size is None else (self.size,)

    def _zip(self, size):
        path = self.get_abspath(self.item_id, self.batch_id, size)
        return path if os.path.isfile(path) else None

    def _remote(self, size, uploader):
        path = self.get_relpath(self.item_id, self.batch_id, size)
        return uploader.is_uploaded(os.path.basename(os.path.dirname(path)), os.path.basename(path))

    def process_pending(self, upload=False, finalize=False, test=True, uploader=None):
        \"\"\"Upload staged ZIPs and optionally commit a fully verified batch.

        A failed upload or missing ZIP leaves local cover files and DB URLs intact.
        Repeated calls are safe: an already uploaded ZIP is skipped.
        \"\"\"
        uploader = uploader or Uploader()
        with batch_lock(self.item_id, self.batch_id):
            for size in self._sizes():
                path = self._zip(size)
                if path is None:
                    continue
                with zipfile.ZipFile(path) as zf:
                    if zf.testzip() is not None or count_files_in_zip(path) == 0:
                        raise ValueError(f'Invalid or empty cover ZIP: {path}')
                if upload and not test and not self._remote(size, uploader):
                    item = os.path.basename(os.path.dirname(path))
                    uploader.upload(item, [path])
            if finalize and not test:
                self.finalize(test=False, uploader=uploader, locked=True)

    def finalize(self, start_id=None, test=True, uploader=None, locked=False):
        \"\"\"Switch DB references only after every size is present remotely.\"\"\"
        if start_id is not None and int(start_id) "'!= self.start_id:
            raise ValueError('"'start_id does not belong to this batch')
        if not locked:
            with batch_lock(self.item_id, self.batch_id):
                return self.finalize(start_id, test, uploader, locked=True)
        uploader = uploader or Uploader()
        missing = [size or 'original' for size in SIZES if not self._remote(size, uploader)]
        if missing:
            raise RuntimeError(f'Batch {self.item_id}_{self.batch_id} missing uploaded ZIPs: {\", \".join(missing)}')
        if test:
            return
        covers = CoverDB().get_archived_batch(self.start_id)
        CoverDB.update_completed_batch(self.item_id, self.batch_id)
        for cover in covers:
            Cover(cover).delete_files()
        for size in SIZES:
            path = self._zip(size)
            if path:
                os.remove(path)


@contextmanager
def batch_lock(item_id, batch_id):
    \"\"\"Serialize archive writers and finalizers for one batch on shared storage.\"\"\"
    item_id, batch_id = Batch._norm_ids(item_id, batch_id)
    lockdir = os.path.join(config.data_root, 'items', '.locks')
    os.makedirs(lockdir, exist_ok=True)
    path = os.path.join(lockdir, f'covers_{item_id}_{batch_id}.lock')
    with open(path, 'a+b') as lockfile:
        fcntl.flock(lockfile, fcntl.LOCK_EX | fcntl.LOCK_NB)
        try:
            yield
        finally:
            fcntl.flock(lockfile, fcntl.LOCK_UN)


def _zip_path_from_name(name):
    match = IMAGE_NAME.fullmatch(name)
    if not match:
        raise ValueError(f'Invalid cover image name: {name}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match['id'])
    return Batch.get_abspath(item_id, batch_id, (match['size'] or '').lower())


def open_zipfile(name):
    \"\"\"Open the batch ZIP for a canonical image filename.\"\"\"
    path = _zip_path_from_name(name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, mode='a', compression=zipfile.ZIP_STORED, allowZip64=True)


def get_zipfile(name):
    return open_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as zf:
        return sum(info.filename.lower().endswith('.jpg') for info in zf.infolist())


class ZipManager:
    \"\"\"Append uncompressed ZIP members once, including across retries.\"\"\"

    def __init__(self):
        self.zipfiles = {}
        self.members = {}

    def get_zipfile(self, name):
        path = _zip_path_from_name(name)
        if path not in self.zipfiles:
            zf = open_zipfile(name)
            self.zipfiles[path] = zf
            self.members[path] = set(zf.namelist())
        return self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        zf = self.get_zipfile(name)
        path = zf.filename
        if name in self.members[path]:
            return name
        info = zipfile.ZipInfo(name, time.localtime(max(mtime, 315532800))[:6])
        info.compress_type = zipfile.ZIP_STORED
        with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
            while chunk := source.read(1024 * 1024):
                target.write(chunk)
        self.members[path].add(name)
        return name

    def close(self):
        for zf in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()
        self.members.clear()


