        if not coverdb.is_closed_batch(self.start_id):
            raise RuntimeError(f'Batch {self.item_id}_{self.batch_id} is still receiving covers')
        pending = [cover for cover in coverdb.get_archived_batch(self.start_id) if not cover.uploaded]
        if not pending:
            return
        for size in SIZES:
            path = self._zip(size)
